WITH customer_stats AS (SELECT customer_id, ROUND(STDDEV(balance), 2) AS stddev_balance, MAX(balance) - MIN(balance) AS balance_range FROM accounts WHERE opened_date < '2024-10-05' GROUP BY customer_id) SELECT c.id, c.credit_limit, cs.stddev_balance, cs.balance_range FROM customers c INNER JOIN customer_stats cs ON c.id = cs.customer_id WHERE cs.balance_range > 27 ORDER BY stddev_balance DESC, id LIMIT 20
